def eval_postfix(tokens):
    tumpukan = []
    for token in tokens:
        if token in "+-*/":
            b = tumpukan.pop()
            a = tumpukan.pop()
            if token == "+": tumpukan.append(a + b)
            elif token == "-": tumpukan.append(a - b)
            elif token == "*": tumpukan.append(a * b)
            elif token == "/": tumpukan.append(int(a / b))
        else:
            tumpukan.append(int(token))
    return tumpukan[0]
